pt:
//【ふき】
<voice name='ふき' class='ふき' src='voice/ma02/0100170b05'>
//「え!?　あああ、いえ、違いますっ」
"Hã!? Ahh! N-Não é isso que eu quis dizer!"

en:
//【景明】
<voice name='景明' class='景明' src='voice/ma02/0100180a00'>
